  'help.cat.getting_started.title': 'Primeros pasos',
  'help.cat.getting_started.desc': '¿Eres nuevo en The English Hub? Empieza aquí.',
  'help.cat.courses.title': 'Cursos y aprendizaje',
  'help.cat.courses.desc': 'Entender el contenido y la estructura de nuestros cursos.',
  'help.cat.mocks.title': 'Exámenes de prueba',
