  'help.cat.practice.title': 'Práctica y repaso',
  'help.cat.practice.desc': 'Perfecciona tus habilidades con práctica específica.',
  'help.cat.billing.title': 'Cuenta y facturación',
  'help.cat.billing.desc': 'Gestiona tu suscripción y tu cuenta.',
  'help.cat.schools.title': 'Colegios y profesores',
  'help.cat.schools.desc': 'Información para colegios y personal docente.',
  'help.cat.parents.title': 'Padres',
