  'cambridge.hub.skills.composition.label': 'Habilidades de composición',
  'cambridge.hub.skills.composition.desc':
    'Escritura narrativa, descriptiva y estrategias del esquema de calificación',
  'cambridge.hub.tools.marking.title': 'Corrección de redacciones con IA',
  'cambridge.hub.tools.marking.desc': 'Envía una redacción para obtener feedback con IA',
